import s from './FrostBakery.module.css'
import Brand from './Brand'
import FindUs from './FindUs'
import SocialLinks from './SocialLinks'

export default function FrostBakery({ d }) {
  const hasServices = d.services?.length > 0
  const heroSubtitle = d.tagline || d.about?.[0]?.p || ''
  const nameWords = d.name.split(' ')
  const lastName = nameWords.pop()
  const restName = nameWords.join(' ')

  return (
    <div className={s.root}>
      {/* Sidebar Navigation */}
      <aside className={s.sidebar} aria-label="Main navigation">
        <div className={s.sidebarBrand}>
          <Brand d={d} />
          {d.tagline && <div className={s.sidebarTagline}>{d.tagline}</div>}
        </div>

        <nav className={s.sidebarNav}>
          <ul>
            <li><a href="#hero" className={s.navLink}><span className={s.navIcon}>◈</span> Home</a></li>
            {hasServices && (
              <li><a href="#services" className={s.navLink}><span className={s.navIcon}>✿</span> Services</a></li>
            )}
            <li><a href="#findus" className={s.navLink}><span className={s.navIcon}>⌖</span> Find Us</a></li>
          </ul>
        </nav>

        {d.hours?.length > 0 && (
          <div className={s.sidebarFooter}>
            <strong>Hours</strong>
            {d.hours.map((h, i) => (
              <div key={i}>{h.day}: {h.time}</div>
            ))}
          </div>
        )}
      </aside>

      {/* Main Content */}
      <main className={s.main}>
        {/* Hero Section */}
        <section className={s.hero} id="hero">
          <div className={s.heroContent}>
            {d.tagline && <div className={s.heroBadge}>{d.tagline}</div>}
            <h1 className={s.heroTitle}>
              {restName} <em>{lastName}</em>
            </h1>
            {heroSubtitle && <p className={s.heroSubtitle}>{heroSubtitle}</p>}
            <div className={s.heroActions}>
              {hasServices ? (
                <a href="#services" className={`${s.btn} ${s.btnPrimary}`}>Explore Services</a>
              ) : (
                <a href="#findus" className={`${s.btn} ${s.btnPrimary}`}>Find Us</a>
              )}
              <a href="#findus" className={`${s.btn} ${s.btnOutline}`}>Visit Us</a>
            </div>
          </div>

          {/* Decorative scoops */}
          <div className={s.heroDeco} aria-hidden="true">
            <div className={`${s.scoop} ${s.scoopStrawberry}`}><div className={s.scoopHighlight} /></div>
            <div className={`${s.scoop} ${s.scoopMint}`}><div className={s.scoopHighlight} /></div>
            <div className={`${s.scoop} ${s.scoopVanilla}`}><div className={s.scoopHighlight} /></div>
          </div>
        </section>

        {/* Services Section (adapted from Flavor Wheel) */}
        {hasServices && (
          <section className={`${s.section} ${s.sectionAlt} ${s.servicesSection}`} id="services">
            <div className={s.sectionHeader}>
              <span className={s.sectionLabel}>Our Menu</span>
              <h2 className={s.sectionTitle}>What we offer</h2>
              <p className={s.sectionDesc}>
                Handcrafted with care, using quality ingredients.
              </p>
            </div>

            <div className={s.servicesGrid}>
              {d.services.map((service, idx) => (
                <div className={s.serviceCard} key={idx}>
                  <div className={`${s.swatch} ${s[`swatch${idx % 4}`]}`} />
                  <div className={s.serviceInfo}>
                    <h3 className={s.serviceName}>{service.title}</h3>
                    {service.desc && <p className={s.serviceDesc}>{service.desc}</p>}
                    {service.price && <div className={s.servicePrice}>${service.price}</div>}
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Find Us Component */}
        <FindUs d={d} />

        {/* Footer */}
        <footer className={s.footer}>
          <div className={s.footerTop}>
            <div>
              <Brand d={d} />
              {d.tagline && <p className={s.footerCopy}>{d.tagline}</p>}
            </div>
            <SocialLinks d={d} />
          </div>
          <div className={s.footerBottom}>
            <p>© {new Date().getFullYear()} {d.name}. All rights reserved.</p>
          </div>
        </footer>
      </main>
    </div>
  )
}

/* Frost Bakery - CSS Modules */
.root {
  /* Vitrina spine roles derived from original palette */
  --vt-surface: #F4F1DE;       /* cream */
  --vt-surface-2: #FFFFFF;     /* white */
  --vt-surface-deep: #3D405B;  /* navy */
  --vt-ink: #3D405B;           /* navy */
  --vt-ink-soft: #575A78;      /* navy-light */
  --vt-on-deep: #F4F1DE;       /* cream for text on deep */
  --vt-accent: #E07A5F;        /* terracotta */
  --vt-on-accent: #FFFFFF;     /* white on accent */
  --vt-accent-ink: #C4603F;    /* terracotta-dark (for contrast) */
  --vt-accent-on-deep: #A8CFBA; /* sage-light for accent on deep */
  --vt-line: rgba(61, 64, 91, 0.15);

  /* Fonts */
  --font-heading: 'Lora', Georgia, serif;
  --font-body: 'Manrope', 'Segoe UI', sans-serif;

  /* Spacing */
  --sidebar-width: 260px;
  --section-pad: clamp(3rem, 6vw, 6rem);
  --gap: clamp(1rem, 2.5vw, 2rem);

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  /* Shadows */
  --shadow-card: 0 4px 24px rgba(61, 64, 91, 0.08);
  --shadow-hover: 0 8px 40px rgba(61, 64, 91, 0.14);

  /* Transitions */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --duration: 0.5s;

  font-family: var(--font-body);
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  line-height: 1.7;
  overflow-x: hidden;
  display: flex;
  min-height: 100vh;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.root h1,
.root h2,
.root h3,
.root h4 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

.root a {
  color: inherit;
  text-decoration: none;
}

.root img {
  max-width: 100%;
  display: block;
}

.root ul {
  list-style: none;
}

.root button {
  font-family: var(--font-body);
  cursor: pointer;
  border: none;
  background: none;
}

/* =========== Sidebar =========== */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: var(--sidebar-width);
  height: 100vh;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
}

.sidebarBrand {
  padding: 2rem 1.5rem 1.5rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.sidebarTagline {
  font-size: 0.75rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-top: 0.35rem;
}

.sidebarNav {
  flex: 1;
  padding: 1.5rem 0;
}

.sidebarNav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.navLink {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: rgba(244, 241, 222, 0.85);
  position: relative;
  transition: all 0.3s var(--ease-out);
  min-height: 44px; /* tap target */
}

.navLink::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 70%;
  background: var(--vt-accent);
  border-radius: 0 3px 3px 0;
  transition: transform 0.3s var(--ease-out);
}

.navLink:hover,
.navLink:focus-visible {
  color: var(--vt-on-deep);
  background: rgba(244, 241, 222, 0.06);
  outline: none;
}

.navLink:hover::before,
.navLink:focus-visible::before {
  transform: translateY(-50%) scaleY(1);
}

.navLink:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.navIcon {
  width: 20px;
  text-align: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.sidebarFooter {
  padding: 1.5rem;
  border-top: 1px solid rgba(244, 241, 222, 0.1);
  font-size: 0.78rem;
  color: rgba(244, 241, 222, 0.7);
  line-height: 1.6;
}

.sidebarFooter strong {
  color: var(--vt-accent-on-deep);
  font-weight: 600;
}

/* =========== Main =========== */
.main {
  margin-left: var(--sidebar-width);
  min-height: 100vh;
  flex: 1;
}

/* =========== Hero =========== */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: var(--section-pad);
  background:
    radial-gradient(ellipse at 20% 80%, rgba(129, 178, 154, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, rgba(224, 122, 95, 0.12) 0%, transparent 50%),
    var(--vt-surface);
  overflow: hidden;
}

.heroContent {
  max-width: 640px;
  position: relative;
  z-index: 2;
  animation: fadeInUp 0.7s var(--ease-out);
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

.heroBadge {
  display: inline-block;
  padding: 0.4rem 1rem;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 50px;
  margin-bottom: 1.5rem;
}

.heroTitle {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
}

.heroTitle em {
  color: var(--vt-accent);
  font-style: italic;
}

.heroSubtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

/* Decorative scoops */
.heroDeco {
  position: absolute;
  right: -2%;
  top: 50%;
  transform: translateY(-50%);
  width: clamp(280px, 35vw, 500px);
  height: clamp(280px, 35vw, 500px);
  z-index: 1;
}

.scoop {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.08), 0 6px 20px rgba(0, 0, 0, 0.06);
}

.scoopHighlight {
  position: absolute;
  width: 25%;
  height: 25%;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  top: 15%;
  left: 20%;
  filter: blur(6px);
}

.scoopStrawberry {
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at 35% 35%, #f4a4b8, var(--vt-accent));
  top: 0;
  right: 10%;
}

.scoopMint {
  width: 50%;
  height: 50%;
  background: radial-gradient(circle at 35% 35%, #a8cfba, #5f8e73);
  bottom: 8%;
  right: 0;
}

.scoopVanilla {
  width: 45%;
  height: 45%;
  background: radial-gradient(circle at 35% 35%, #fff5e0, #e8e3c8);
  bottom: 15%;
  left: 5%;
}

/* =========== Buttons =========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all 0.3s var(--ease-out);
  min-height: 44px; /* tap target */
}

.btnPrimary {
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
}

.btnPrimary:hover,
.btnPrimary:focus-visible {
  background: var(--vt-accent);
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(224, 122, 95, 0.35);
}

.btnOutline {
  border: 2px solid var(--vt-ink);
  color: var(--vt-ink);
  background: transparent;
}

.btnOutline:hover,
.btnOutline:focus-visible {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  transform: translateY(-2px);
}

.btn:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* =========== Sections =========== */
.section {
  padding: var(--section-pad);
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.sectionHeader {
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}

.sectionLabel {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.75rem;
}

.sectionTitle {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--vt-ink);
  letter-spacing: -0.02em;
}

.sectionDesc {
  margin-top: 0.75rem;
  font-size: 1.05rem;
  color: var(--vt-ink-soft);
  max-width: 560px;
}

/* =========== Services Grid (originally flavor cards) =========== */
.servicesSection {
  overflow: hidden;
  padding-left: 0;
  padding-right: 0;
}

.servicesSection .sectionHeader {
  padding-left: var(--section-pad);
  padding-right: var(--section-pad);
}

.servicesGrid {
  display: flex;
  gap: 1.25rem;
  padding: 1rem var(--section-pad) 2rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.serviceCard {
  flex: 0 0 340px;
  scroll-snap-align: start;
  background: var(--vt-surface-2);
  border-radius: var(--radius-lg);
  padding: 1.4rem 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 1.15rem;
  transition: all 0.35s var(--ease-out);
  position: relative;
  overflow: hidden;
}

.serviceCard:hover {
  box-shadow: var(--shadow-hover);
  transform: scale(1.03);
}

.swatch {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  flex-shrink: 0;
  position: relative;
  box-shadow: inset 0 -4px 10px rgba(0, 0, 0, 0.08);
}

.swatch::after {
  content: '';
  position: absolute;
  width: 35%;
  height: 35%;
  background: rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  top: 12%;
  left: 18%;
  filter: blur(3px);
}

.swatch0 { background: radial-gradient(circle at 35% 35%, #fce4b8, #e6c68a); }
.swatch1 { background: radial-gradient(circle at 35% 35%, #a8d8ea, #6bb7d4); }
.swatch2 { background: radial-gradient(circle at 35% 35%, #c9b3d6, #9b7eb8); }
.swatch3 { background: radial-gradient(circle at 35% 35%, #b6d7a8, #7ab55c); }

.serviceInfo {
  min-width: 0;
}

.serviceName {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0.15rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.serviceDesc {
  font-size: 0.82rem;
  color: var(--vt-ink-soft);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.servicePrice {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--vt-accent-ink);
  margin-top: 0.5rem;
}

/* =========== Footer =========== */
.footer {
  padding: 3rem var(--section-pad) 2rem;
  background: var(--vt-surface-deep);
  color: rgba(244, 241, 222, 0.8);
}

.footerTop {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.footerCopy {
  margin-top: 0.5rem;
  font-size: 0.85rem;
  max-width: 300px;
}

.footerBottom {
  padding-top: 1.5rem;
  font-size: 0.78rem;
  text-align: center;
  color: rgba(244, 241, 222, 0.6);
}

/* =========== Responsive =========== */
@media (max-width: 1024px) {
  .root {
    flex-direction: column;
  }

  .sidebar {
    position: static;
    width: 100%;
    height: auto;
    flex-direction: row;
    align-items: center;
    padding: 0.5rem 1rem;
    overflow-y: visible;
    z-index: 10;
  }

  .sidebarBrand {
    padding: 0.5rem;
    border-bottom: none;
  }

  .sidebarTagline {
    display: none;
  }

  .sidebarNav {
    flex: 1;
    padding: 0;
  }

  .sidebarNav ul {
    flex-direction: row;
    justify-content: flex-end;
  }

  .navLink {
    padding: 0.5rem 0.75rem;
    min-height: 44px;
  }

  .sidebarFooter {
    display: none;
  }

  .main {
    margin-left: 0;
  }

  .heroDeco {
    opacity: 0.3;
    right: -10%;
  }
}

@media (max-width: 640px) {
  .hero {
    padding-top: 5rem;
    min-height: auto;
  }

  .heroDeco {
    opacity: 0.2;
    right: -15%;
    width: 220px;
    height: 220px;
  }

  .servicesGrid {
    gap: 0.75rem;
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }

  .serviceCard {
    flex-basis: 280px;
  }

  .footerTop {
    flex-direction: column;
  }

  .section {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }

  .sidebar {
    flex-wrap: wrap;
  }

  .sidebarNav ul {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .root,
  .root *,
  .root *::before,
  .root *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
